    @objc func issueObserverPairingTokenFromMenu(_ sender: Any?) {
        Task { @MainActor in
            let logger = Logger(subsystem: "continuum.auth", category: "pairing")
            var startedListener: LocalPairingEndpointListener?
            do {
                let service = try ensureCompanionAuthService()
                let ttl: TimeInterval = 300
                let instance = try await service.instance()
                let grant = try await service.issuePairingCredential(scopes: .observer, ttl: ttl, label: "Debug Observer")
                let expiresAt = grant.expiresAt ?? Date().addingTimeInterval(ttl)
                localPairingListener?.stop()
                let listener = try LocalPairingEndpointListener.start(
                    authService: service,
                    advertisedHost: LocalPairingEndpointListener.preferredAdvertisedHost(),
                    expiresAt: expiresAt,
                    acceptedCredential: grant.credential,
                    onExchangeSuccess: { [weak self] exchange in
                        await self?.localPairingExchangeDidSucceed(exchange)
                    }
                )
                startedListener = listener
                localPairingListener = listener
                let url = PairingURL.issue(
                    credential: grant.credential,
                    scopes: grant.scopes,
                    instanceId: instance.id,
                    endpoint: listener.endpointURL,
                    relay: Self.advertisedRelayURL(advertisedHost: LocalPairingEndpointListener.preferredAdvertisedHost())
                )
                let cameraURL = PairingURL.cameraBootstrapURL(pairingURL: url, endpoint: listener.endpointURL)
                copyPairingURLToPasteboard(cameraURL)
                logger.notice("pairing listener ready endpoint=\(listener.endpointURL.absoluteString, privacy: .public) expiresAt=\(expiresAt.ISO8601Format(), privacy: .public) scope=\(grant.scopes.rawValue, privacy: .public)")
                presentPairingURL(url, cameraURL: cameraURL, listener: listener, expiresAt: expiresAt)
            } catch {
                startedListener?.stop()
                if let startedListener, localPairingListener === startedListener {
                    localPairingListener = nil
                }
                logger.error("pairing listener setup failed")
                presentPairingError()
            }
        }
    }

    private func ensureCompanionAuthService() throws -> CompanionAuthService {
        if let companionAuthService { return companionAuthService }
        let service = try CompanionAuthService(
            authDirectory: Self.resolveAuthDirectory(applicationSupportDirectory: Self.resolveAppSupportDir(smokeTest: smokeTestEnabled)),
            instanceDisplayName: Host.current().localizedName ?? "Continuum"
        )
        companionAuthService = service
        return service
    }

    private func registerActiveSessionTokensWithRelay(_ transport: RelaySyncTransport) async {
        do {
            let service = try ensureCompanionAuthService()
            let tokens = await service.activeSessionTokens()
            var registered = 0
            for entry in tokens {
                do {
                    try await transport.registerToken(entry.token, scopes: entry.scopes)
                    registered += 1
                } catch {
                    Self.appendCompanionSyncLog("reason=relay-token-sync-FAILED error=\(String(describing: error))")
                }
            }
            Self.appendCompanionSyncLog("reason=relay-token-sync registered=\(registered)/\(tokens.count)")
        } catch {
            Self.appendCompanionSyncLog("reason=relay-token-sync-FAILED auth-service error=\(String(describing: error))")
        }
    }

    /// The relay URL to advertise in a pairing link: the configured relay,
    /// with a loopback host rewritten to the LAN-reachable one (a phone
    /// can't dial the Mac's 127.0.0.1). A non-loopback URL (the VPS later)
    /// passes through untouched. Nil when not in relay mode.
    private static func advertisedRelayURL(advertisedHost: String) -> URL? {
        guard let config = RelayClientConfig.resolve() else { return nil }
        guard let host = config.baseURL.host, host == "127.0.0.1" || host == "localhost" else {
            return config.baseURL
        }
        var components = URLComponents(url: config.baseURL, resolvingAgainstBaseURL: false)
        components?.host = advertisedHost
        return components?.url
    }

    private func copyPairingURLToPasteboard(_ url: URL) {
        NSPasteboard.general.clearContents()
        NSPasteboard.general.setString(url.absoluteString, forType: .string)
    }

    private func presentPairingURL(_ url: URL, cameraURL: URL, listener: LocalPairingEndpointListener, expiresAt: Date) {
        let alert = NSAlert()
        alert.messageText = "Continuum LAN Pairing"
        alert.informativeText = """
        Camera-compatible pairing link copied to the clipboard. Scan the QR code with iPhone Camera; it opens a local Mac page that opens Continuum.

        If you are already in Continuum, Pair this phone > Scan Pairing QR also accepts this code.

        Status: Listening on \(listener.endpointURL.absoluteString)
        Expires: \(expiresAt.formatted(date: .abbreviated, time: .standard))
        Scope: Observer

        QR URL: \(cameraURL.absoluteString)
        Continuum link: \(url.absoluteString)
        """
        if let qrImage = makePairingQRCode(for: cameraURL) {
            let imageView = NSImageView(image: qrImage)
            imageView.imageScaling = .scaleNone
            imageView.translatesAutoresizingMaskIntoConstraints = false
            NSLayoutConstraint.activate([
                imageView.widthAnchor.constraint(equalToConstant: qrImage.size.width),
                imageView.heightAnchor.constraint(equalToConstant: qrImage.size.height)
            ])
            alert.accessoryView = imageView
        }
        alert.alertStyle = .informational
        alert.addButton(withTitle: "Copy URL")
        alert.addButton(withTitle: "Stop Listener")
        alert.addButton(withTitle: "OK")
        let response = alert.runModal()
        if response == .alertFirstButtonReturn {
            copyPairingURLToPasteboard(cameraURL)
        } else if response == .alertSecondButtonReturn {
            listener.stop()
            if localPairingListener === listener {
                localPairingListener = nil
            }
        }
    }

    private func makePairingQRCode(for url: URL) -> NSImage? {
        guard let filter = CIFilter(name: "CIQRCodeGenerator"),
              let data = url.absoluteString.data(using: .utf8) else {
            return nil
        }
        filter.setValue(data, forKey: "inputMessage")
        filter.setValue("M", forKey: "inputCorrectionLevel")
        guard let rawOutputImage = filter.outputImage else { return nil }
        let outputImage = rawOutputImage.cropped(to: rawOutputImage.extent.integral)

        // Render an actual black-on-white bitmap with a quiet zone and integer
        // module scale. NSCIImageRep can leave the QR transparent/interpolated in
        // an NSAlert, which makes physical iPhone scanning unreliable.
        let moduleQuietZone = CGFloat(4)
        let qrExtent = outputImage.extent.integral
        let paddedExtent = CGRect(
            x: 0,
            y: 0,
            width: qrExtent.width + moduleQuietZone * 2,
            height: qrExtent.height + moduleQuietZone * 2
        )
        let whiteBackground = CIImage(color: CIColor.white).cropped(to: paddedExtent)
        let blackOnWhite = outputImage
            .applyingFilter("CIFalseColor", parameters: [
                "inputColor0": CIColor.black,
                "inputColor1": CIColor.white
            ])
            .transformed(by: CGAffineTransform(
                translationX: moduleQuietZone - qrExtent.minX,
                y: moduleQuietZone - qrExtent.minY
            ))
            .composited(over: whiteBackground)

        let targetPixels = CGFloat(360)
        let scale = max(1, floor(targetPixels / max(paddedExtent.width, paddedExtent.height)))
        let scaled = blackOnWhite.transformed(by: CGAffineTransform(scaleX: scale, y: scale))
        let context = CIContext(options: nil)
        guard let cgImage = context.createCGImage(scaled, from: scaled.extent.integral) else { return nil }
        return NSImage(cgImage: cgImage, size: NSSize(width: scaled.extent.width, height: scaled.extent.height))
    }

    private func presentPairingError() {
        let alert = NSAlert()
        alert.messageText = "Could not start LAN pairing"
        alert.informativeText = "The pairing listener was not started. Try again from Debug > Auth."
        alert.alertStyle = .warning
        alert.addButton(withTitle: "OK")
        alert.runModal()
    }

    @MainActor
    private func localPairingExchangeDidSucceed(_ exchange: CompanionPairingExchange) {
        Logger(subsystem: "continuum.auth", category: "pairing").notice(
            "paired companion device=\(exchange.device.id.uuidString, privacy: .public) scope=\(exchange.device.scopes.rawValue, privacy: .public); scheduling companion publish"
        )
        if let listener = localPairingListener {
            listener.stop()
            localPairingListener = nil
        }
        if let relaySyncTransport {
            let token = exchange.session.token
            let scopes = exchange.session.scopes
            Task {
                do {
                    try await relaySyncTransport.registerToken(token, scopes: scopes)
                    Self.appendCompanionSyncLog("reason=relay-token-registered device=\(exchange.device.id) scopes=\(scopes.rawValue)")
                } catch {
                    Self.appendCompanionSyncLog("reason=relay-token-register-FAILED device=\(exchange.device.id) error=\(String(describing: error))")
                }
            }
        }
        scheduleCompanionSyncPublish(reason: .pairing, diagnosticsReason: "pairing", debounce: 0.2)
    }

    @objc func publishCompanionSyncNowFromMenu(_ sender: Any?) {
        Task { @MainActor in
