    private func activeZoneProjectEntry() -> ProjectEntry? {
        guard let projectId = canvasView?.activeZone?.projectId ?? workspaceRuntime?.activeController?.project.id,
              let registry = try? registryStore?.loadOrEmpty()
        else { return nil }
        return registry.projects.first(where: { $0.id == projectId })
    }

    private func presentLockContentionUXIfNeeded(projectRoot: URL, registry: Registry) throws -> ZoneRuntimeController {
        var candidate = projectRoot
        while true {
            do {
                return try ZoneRuntimeController(root: candidate)
            } catch let ProjectLockError.alreadyLocked(lockFile) {
                switch presentProjectLockAlert(lockFile: lockFile) {
                case .chooseAnotherProject:
                    let request = ProjectLaunchCoordinator.PickerRequest(
                        reason: .noUsableProject,
                        rows: ProjectPickerModel.makeRows(registry: registry)
                    )
                    let picker = ProjectPickerPanel(request: request)
                    guard let selected = picker.runModal() else {
                        NSApp.terminate(nil)
                        throw CocoaError(.userCancelled)
                    }
                    candidate = selected
                case .openAnyway:
                    return try ZoneRuntimeController(root: candidate, acquireLock: false)
                case .quit:
                    NSApp.terminate(nil)
                    throw CocoaError(.userCancelled)
                }
            }
        }
    }

    private enum ProjectLockAlertChoice {
        case chooseAnotherProject
        case openAnyway
        case quit
    }

    private func presentProjectLockAlert(lockFile: URL) -> ProjectLockAlertChoice {
        let config = ProjectLockPolicy.alertConfiguration(lockFile: lockFile)
        let alert = NSAlert()
        alert.messageText = config.message
        alert.informativeText = config.informative
        alert.alertStyle = .warning
        for title in config.buttonTitles {
            alert.addButton(withTitle: title)
        }
        if config.buttonTitles.indices.contains(config.defaultButtonIndex) {
            alert.buttons[config.defaultButtonIndex].keyEquivalent = "\r"
        }
        let response = alert.runModal()
        switch response {
        case .alertFirstButtonReturn:
            return .chooseAnotherProject
        case .alertSecondButtonReturn:
            return .openAnyway
        default:
            return .quit
        }
    }

    /// Ticket 87: render a Component Lab gallery view offscreen to a PNG.
    /// Dark backing to match the agent-tile context the chips render against.
    private static func renderComponentSnapshot(named name: String, to path: String) -> Bool {
        let content: NSView
        let backingSize: NSSize
        switch name {
        case "status-chips":
            content = LabCatalog.makeStatusChipGalleryView()
            backingSize = NSSize(width: 360, height: 280)
        case "managed-agent":
            let tile = LabCatalog.makeManagedAgentFixtureView(includeApproval: false)
            tile.frame = NSRect(x: 0, y: 0, width: 460, height: 520)
            content = tile
            backingSize = NSSize(width: 460, height: 520)
        default:
            FileHandle.standardError.write(Data("unknown component snapshot: \(name)\n".utf8))
            return false
        }
        content.translatesAutoresizingMaskIntoConstraints = false
        let backing = NSView(frame: NSRect(x: 0, y: 0, width: backingSize.width, height: backingSize.height))
        backing.wantsLayer = true
        backing.layer?.backgroundColor = NSColor(srgbRed: 0.08, green: 0.10, blue: 0.13, alpha: 1).cgColor
        backing.addSubview(content)
        NSLayoutConstraint.activate([
            content.leadingAnchor.constraint(equalTo: backing.leadingAnchor),
            content.topAnchor.constraint(equalTo: backing.topAnchor),
            content.trailingAnchor.constraint(equalTo: backing.trailingAnchor),
            content.bottomAnchor.constraint(equalTo: backing.bottomAnchor),
        ])
        backing.layoutSubtreeIfNeeded()
        guard let rep = backing.bitmapImageRepForCachingDisplay(in: backing.bounds) else { return false }
        backing.cacheDisplay(in: backing.bounds, to: rep)
        guard let data = rep.representation(using: .png, properties: [:]) else { return false }
        do {
            try data.write(to: URL(fileURLWithPath: path))
            return true
        } catch {
            FileHandle.standardError.write(Data("snapshot write failed: \(error)\n".utf8))
            return false
        }
    }

    private static func resolveProjectRoot(smokeTest: Bool, registry: Registry) throws -> URL {
        if smokeTest, ProcessInfo.processInfo.environment["CONTINUUM_PROJECT_ROOT"] == nil {
            let temp = FileManager.default.temporaryDirectory
                .appendingPathComponent("continuum-smoke-project-\(UUID().uuidString)", isDirectory: true)
            try? FileManager.default.createDirectory(at: temp, withIntermediateDirectories: true)
            return temp
        }

        if let envRoot = ProcessInfo.processInfo.environment["CONTINUUM_PROJECT_ROOT"], envRoot.hasPrefix("/") {
            return try requestProjectFolderAccessIfNeeded(URL(fileURLWithPath: envRoot, isDirectory: true))
        }

        // Do not probe a remembered project inside macOS privacy-protected folders before
        // the user has granted access. FileManager probes against ~/Documents can trigger
        // repeated TCC prompts while boot restore is also trying to start terminals/file
        // trees. Route that path through one explicit NSOpenPanel grant first.
        if registry.settings.openLastProjectOnLaunch,
           let projectId = registry.lastActiveProjectId,
           let entry = registry.projects.first(where: { $0.id == projectId }),
           entry.rootPath.hasPrefix("/"),
           requiresExplicitProjectFolderGrant(URL(fileURLWithPath: entry.rootPath, isDirectory: true)) {
            return try requestProjectFolderAccessIfNeeded(URL(fileURLWithPath: entry.rootPath, isDirectory: true))
        }

        switch ProjectLaunchCoordinator.decide(registry: registry) {
        case let .open(url):
            return try requestProjectFolderAccessIfNeeded(url)
        case let .presentPicker(request):
            let picker = ProjectPickerPanel(request: request)
            guard let selected = picker.runModal() else {
                NSApp.terminate(nil)
                throw CocoaError(.userCancelled)
            }
            return try requestProjectFolderAccessIfNeeded(selected)
        }
    }

    private static func requiresExplicitProjectFolderGrant(_ url: URL) -> Bool {
        let path = url.standardizedFileURL.path
        let home = FileManager.default.homeDirectoryForCurrentUser.standardizedFileURL.path
        let protectedRoots = ["Documents", "Desktop", "Downloads"].map { "\(home)/\($0)" }
        return protectedRoots.contains { path == $0 || path.hasPrefix($0 + "/") }
    }

    private static func requestProjectFolderAccessIfNeeded(_ url: URL) throws -> URL {
        let standardized = url.standardizedFileURL
        guard requiresExplicitProjectFolderGrant(standardized) else { return standardized }
        let grantKey = projectFolderGrantAcknowledgementKey(for: standardized)
        if UserDefaults.standard.bool(forKey: grantKey) {
            return standardized
        }

        let alert = NSAlert()
        alert.messageText = "Grant Continuum access to this project folder"
        alert.informativeText = "Continuum needs access to restore this project once. Select the project folder in the next dialog; if you cancel, Continuum will quit instead of repeatedly triggering macOS privacy prompts.\n\n\(standardized.path)"
        alert.addButton(withTitle: "Choose Folder…")
        alert.addButton(withTitle: "Quit")
        guard alert.runModal() == .alertFirstButtonReturn else {
            NSApp.terminate(nil)
            throw CocoaError(.userCancelled)
        }

        let panel = NSOpenPanel()
        panel.message = "Choose the Continuum project folder"
        panel.prompt = "Grant Access"
        panel.canChooseDirectories = true
        panel.canChooseFiles = false
        panel.allowsMultipleSelection = false
        panel.resolvesAliases = true
        panel.directoryURL = standardized.deletingLastPathComponent()
        panel.nameFieldStringValue = standardized.lastPathComponent

        guard panel.runModal() == .OK, let selected = panel.url?.standardizedFileURL else {
            NSApp.terminate(nil)
            throw CocoaError(.userCancelled)
        }
        UserDefaults.standard.set(true, forKey: projectFolderGrantAcknowledgementKey(for: selected))
        return selected
    }

    private static func projectFolderGrantAcknowledgementKey(for url: URL) -> String {
        let path = url.standardizedFileURL.path
        let encoded = Data(path.utf8).base64EncodedString()
            .replacingOccurrences(of: "/", with: "_")
            .replacingOccurrences(of: "+", with: "-")
            .replacingOccurrences(of: "=", with: "")
        return "continuum.projectFolderGrantAcknowledged.\(encoded)"
    }

    private static func resolveAppSupportDir(smokeTest: Bool) -> URL? {
        // The logic itself lives in Core (P2A.2) so it is testable; nil still
